modules["UI/Elements/Button"] = function(...)
-- Button.
local import = ...

local Card = import("UI/Card")
local Elements = import("UI/Elements/Base")
local Fonts = import("Core/Fonts")
local FONT_MED = Fonts.FONT_MED
local Util = import("Core/Util")
local Create, Tween, Corner, Safe, IsTouchInput = Util.Create, Util.Tween, Util.Corner, Util.Safe, Util.IsTouchInput
local Binding = import("Theme/Binding")
local Themed = Binding.Themed

function Elements:AddButton(opts)
	opts = opts or {}
	local window, theme = self.Window, self.Theme
	local card, _, cy = Card(self, opts, 0.55)

	local btn = Create("TextButton", {
		Size = UDim2.fromOffset(opts.ButtonWidth or 96, 30),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0, cy),
		AutoButtonColor = false,
		Text = opts.ButtonText or "Run",
		Font = FONT_MED,
		TextSize = 13,
		BorderSizePixel = 0,
		Parent = card,
	})
	Themed(window, btn, { BackgroundColor3 = "Accent", TextColor3 = "AccentText" })
	Corner(btn, 4)
	local press = Create("UIScale", { Parent = btn })

	btn.MouseEnter:Connect(function()
		Tween(btn, { BackgroundColor3 = theme.AccentHover }, 0.12)
	end)
	btn.MouseLeave:Connect(function()
		Tween(btn, { BackgroundColor3 = theme.Accent }, 0.12)
		Tween(press, { Scale = 1 }, 0.12)
	end)
	btn.MouseButton1Down:Connect(function()
		Tween(btn, { BackgroundColor3 = theme.AccentPressed }, 0.06)
		Tween(press, { Scale = 0.95 }, 0.06)
	end)
	btn.MouseButton1Up:Connect(function()
		Tween(btn, { BackgroundColor3 = IsTouchInput() and theme.Accent or theme.AccentHover }, 0.12)
		Tween(press, { Scale = 1 }, 0.2, Enum.EasingStyle.Back)
	end)
	btn.MouseButton1Click:Connect(function()
		Safe(opts.Callback)
	end)

	local obj = { Instance = card }
	function obj:SetText(text)
		btn.Text = text
	end
	return obj
end

return Elements
end

modules["UI/Elements/ColorPicker"] = function(...)
-- Color picker (saturation/value square, hue bar, hex box, presets).
local import = ...

local Card = import("UI/Card")
local Elements = import("UI/Elements/Base")
local Services = import("Core/Services")
local UserInputService = Services.UserInputService
local Fonts = import("Core/Fonts")
local FONT, FONT_MED = Fonts.FONT, Fonts.FONT_MED
local Colors = import("Theme/Colors")
local WHITE, BLACK, RGB, ToHex, FromHex = Colors.WHITE, Colors.BLACK, Colors.RGB, Colors.ToHex, Colors.FromHex
local Util = import("Core/Util")
local Create, Tween, Corner, Safe, SetFlag, IsPress, IsMove, ScrollIntoView = Util.Create, Util.Tween, Util.Corner, Util.Safe, Util.SetFlag, Util.IsPress, Util.IsMove, Util.ScrollIntoView
local Binding = import("Theme/Binding")
local Themed, NewText, Stroke = Binding.Themed, Binding.NewText, Binding.Stroke

local PRESETS = {
	RGB(217, 119, 87),
	RGB(212, 162, 127),
	RGB(235, 219, 188),
	RGB(110, 170, 255),
	RGB(120, 200, 140),
	RGB(167, 125, 240),
	RGB(232, 121, 160),
}

function Elements:AddColorPicker(opts)
	opts = opts or {}
	local window, theme = self.Window, self.Theme
	local color = opts.Default or theme.Accent
	local h, s, v = color:ToHSV()
	local open = false
	local panelH = 198
	local obj = {}

	local card, rowH, cy = Card(self, opts, 0.5)
	card.ClipsDescendants = true
	obj.Instance = card

	local rowButton = Create("TextButton", {
		Size = UDim2.new(1, 0, 0, rowH),
		BackgroundTransparency = 1,
		Text = "",
		Parent = card,
	})
	local swatch = Create("TextButton", {
		Size = UDim2.fromOffset(48, 26),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0, cy),
		BackgroundColor3 = color,
		AutoButtonColor = false,
		Text = "",
		BorderSizePixel = 0,
		Parent = card,
	})
	Corner(swatch, 5)
	Stroke(window, swatch, "Text", 0.75)

	local panel = Create("Frame", {
		Position = UDim2.fromOffset(0, rowH),
		Size = UDim2.new(1, 0, 0, panelH),
		BackgroundTransparency = 1,
		Parent = card,
	})

	-- saturation / value square
	local sv = Create("Frame", {
		Position = UDim2.fromOffset(10, 6),
		Size = UDim2.new(1, -48, 0, 112),
		BackgroundColor3 = Color3.fromHSV(h, 1, 1),
		BorderSizePixel = 0,
		Parent = panel,
	})
	Corner(sv, 5)
	local whiteLayer = Create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = WHITE,
		BorderSizePixel = 0,
		Parent = sv,
	})
	Corner(whiteLayer, 5)
	Create("UIGradient", { Transparency = NumberSequence.new(0, 1), Parent = whiteLayer })
	local blackLayer = Create("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = BLACK,
		BorderSizePixel = 0,
		Parent = sv,
	})
	Corner(blackLayer, 5)
	Create("UIGradient", { Transparency = NumberSequence.new(1, 0), Rotation = 90, Parent = blackLayer })
	local svCursor = Create("Frame", {
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		ZIndex = 3,
		Parent = sv,
	})
	Corner(svCursor, "pill")
	Create("UIStroke", { Color = WHITE, Thickness = 2, Parent = svCursor })
	local svHit = Create("TextButton", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		ZIndex = 4,
		Parent = sv,
	})

	-- hue bar
	local hueBar = Create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -10, 0, 6),
		Size = UDim2.fromOffset(18, 112),
		BackgroundColor3 = WHITE,
		BorderSizePixel = 0,
		Parent = panel,
	})
	Corner(hueBar, 5)
	local hueKeys = {}
	for i = 0, 6 do
		table.insert(hueKeys, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6, 1, 1)))
	end
	Create("UIGradient", { Color = ColorSequence.new(hueKeys), Rotation = 90, Parent = hueBar })
	local hueCursor = Create("Frame", {
		Size = UDim2.new(1, 6, 0, 6),
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		ZIndex = 3,
		Parent = hueBar,
	})
	Corner(hueCursor, 3)
	Create("UIStroke", { Color = WHITE, Thickness = 2, Parent = hueCursor })
	local hueHit = Create("TextButton", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Text = "",
		ZIndex = 4,
		Parent = hueBar,
	})

	-- hex + rgb readout
	local hexBox = Create("TextBox", {
		Position = UDim2.fromOffset(10, 128),
		Size = UDim2.fromOffset(92, 28),
		BorderSizePixel = 0,
		Text = "",
		PlaceholderText = "#RRGGBB",
		Font = FONT_MED,
		TextSize = 13,
		ClearTextOnFocus = false,
		Parent = panel,
	})
	Themed(window, hexBox, {
		BackgroundColor3 = "Control",
		BackgroundTransparency = "ControlTransparency",
		TextColor3 = "Text",
		PlaceholderColor3 = "SubText",
	})
	Corner(hexBox, 4)
	Stroke(window, hexBox, "Stroke", "StrokeTransparency")
	local rgbLabel = NewText(window, panel, "", {
		Position = UDim2.fromOffset(110, 128),
		Size = UDim2.new(1, -120, 0, 28),
		Font = FONT,
		TextSize = 12,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, "SubText")

	-- presets
	local presets = Create("Frame", {
		Position = UDim2.fromOffset(10, 166),
		Size = UDim2.new(1, -20, 0, 20),
		BackgroundTransparency = 1,
		Parent = panel,
	})
	Create("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		Padding = UDim.new(0, 5),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = presets,
	})
	for _, preset in ipairs(opts.Presets or PRESETS) do
		local dot = Create("TextButton", {
			Size = UDim2.fromOffset(20, 20),
			BackgroundColor3 = preset,
			AutoButtonColor = false,
			Text = "",
			BorderSizePixel = 0,
			Parent = presets,
		})
		Corner(dot, "pill")
		Stroke(window, dot, "Text", 0.8)
		dot.MouseButton1Click:Connect(function()
			obj:Set(preset)
		end)
	end

	local function refresh(silent)
		color = Color3.fromHSV(h, s, v)
		sv.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		svCursor.Position = UDim2.fromScale(s, 1 - v)
		hueCursor.Position = UDim2.fromScale(0.5, h)
		swatch.BackgroundColor3 = color
		if not hexBox:IsFocused() then
			hexBox.Text = ToHex(color)
		end
		rgbLabel.Text = string.format(
			"%d, %d, %d",
			math.floor(color.R * 255 + 0.5),
			math.floor(color.G * 255 + 0.5),
			math.floor(color.B * 255 + 0.5)
		)
		SetFlag(opts, color)
		if not silent then
			Safe(opts.Callback, color)
		end
	end

	function obj:Set(newColor, silent)
		if newColor == color then
			return
		end
		h, s, v = newColor:ToHSV()
		refresh(silent)
	end
	function obj:Get()
		return color
	end

	local mode
	local function update(input)
		if mode == "sv" then
			local pos, size = sv.AbsolutePosition, sv.AbsoluteSize
			s = math.clamp((input.Position.X - pos.X) / size.X, 0, 1)
			v = 1 - math.clamp((input.Position.Y - pos.Y) / size.Y, 0, 1)
		elseif mode == "hue" then
			local pos, size = hueBar.AbsolutePosition, hueBar.AbsoluteSize
			h = math.clamp((input.Position.Y - pos.Y) / size.Y, 0, 0.999)
		end
		refresh()
	end
	local function begin(which, input)
		if IsPress(input) then
			mode = which
			if self.Page then
				self.Page.ScrollingEnabled = false
			end
			update(input)
		end
	end
	svHit.InputBegan:Connect(function(input)
		begin("sv", input)
	end)
	hueHit.InputBegan:Connect(function(input)
		begin("hue", input)
	end)
	window:_connect(UserInputService.InputChanged, function(input)
		if mode and IsMove(input) then
			update(input)
		end
	end)
	window:_connect(UserInputService.InputEnded, function(input)
		if mode and IsPress(input) then
			mode = nil
			if self.Page then
				self.Page.ScrollingEnabled = true
			end
		end
	end)

	hexBox.FocusLost:Connect(function()
		local parsed = FromHex(hexBox.Text)
		if parsed then
			obj:Set(parsed)
		end
		hexBox.Text = ToHex(color)
	end)

	local function toggle(state)
		open = state
		Tween(card, { Size = UDim2.new(1, 0, 0, open and (rowH + panelH) or rowH) }, 0.24)
		if open and self.Page then
			ScrollIntoView(self.Page, card)
		end
	end
	rowButton.MouseButton1Click:Connect(function()
		toggle(not open)
	end)
	swatch.MouseButton1Click:Connect(function()
		toggle(not open)
	end)

	refresh(true)
	return obj
end

return Elements
end

modules["UI/Elements/Config"] = function(...)
-- Ready-made config panel: pick, save, load and delete configs, plus auto load / auto save.
local import = ...

local Moon = import("Core/Moon")
local Elements = import("UI/Elements/Base")

function Elements:AddConfigManager()
	local window = self.Window
	local selected = Moon:GetAutoLoad()
	local typedName = ""
	local autoLoad, autoSave

	local function notify(title, content)
		window:Notify({ Title = title, Content = content, Duration = 3 })
	end

	local list = self:AddDropdown({
		Name = "Config",
		Description = "Pick a saved config",
		Options = Moon:ListConfigs(),
		Default = selected,
		Callback = function(value)
			selected = value
		end,
	})

	local function refresh(keep)
		list:Refresh(Moon:ListConfigs(), true)
		list:Set(keep, true)
	end

	self:AddTextbox({
		Name = "New config",
		Placeholder = "name",
		Callback = function(text)
			typedName = text
		end,
	})

	self:AddButton({
		Name = "Save",
		Description = "Saves your current settings",
		ButtonText = "Save",
		Callback = function()
			local name = typedName ~= "" and typedName or selected
			if not name or name == "" then
				notify("Config", "Type a name or pick a config first")
				return
			end
			local ok, result = Moon:SaveConfig(name)
			if ok then
				selected = result
				refresh(result)
				notify("Config saved", result)
			else
				notify("Could not save", tostring(result))
			end
		end,
	})

	self:AddButton({
		Name = "Load",
		Description = "Applies the selected config",
		ButtonText = "Load",
		Callback = function()
			if not selected then
				notify("Config", "Pick a config first")
				return
			end
			local ok, result = Moon:LoadConfig(selected)
			if ok then
				notify("Config loaded", selected .. " (" .. tostring(result) .. " settings)")
			else
				notify("Could not load", tostring(result))
			end
		end,
	})

	self:AddButton({
		Name = "Delete",
		Description = "Deletes the selected config",
		ButtonText = "Delete",
		Callback = function()
			if not selected then
				notify("Config", "Pick a config first")
				return
			end
			local ok, err = Moon:DeleteConfig(selected)
			if ok then
				notify("Config deleted", selected)
				selected = nil
				refresh(nil)
				autoLoad:Set(Moon:GetAutoLoad() ~= nil, true)
			else
				notify("Could not delete", tostring(err))
			end
		end,
	})

	autoLoad = self:AddToggle({
		Name = "Auto load",
		Description = "Loads the selected config when the script starts",
		Default = Moon:GetAutoLoad() ~= nil,
		Callback = function(state)
			if state and not selected then
				notify("Config", "Pick a config first")
				autoLoad:Set(false, true)
				return
			end
			Moon:SetAutoLoad(state and selected or nil)
		end,
	})

	autoSave = self:AddToggle({
		Name = "Auto save",
		Description = "Saves the selected config whenever you change something",
		Default = false,
		Callback = function(state)
			local target = selected or Moon._currentConfig
			if state and not target then
				notify("Config", "Pick or save a config first")
				autoSave:Set(false, true)
				return
			end
			Moon:SetAutoSave(state, target)
		end,
	})

	return { Refresh = refresh }
end

return Elements
end

modules["UI/Elements/Dropdown"] = function(...)
-- Dropdown. The option list opens as a floating popup instead of inside the scrolling page:
--   PC:     anchored under the box (flips above when there is no room); closes when you scroll or move the window
--   Mobile: a centered sheet with a dim backdrop and big touch rows (no nested scrolling)
local import = ...

local Card = import("UI/Card")
local Elements = import("UI/Elements/Base")
local Services = import("Core/Services")
local UserInputService = Services.UserInputService
local Colors = import("Theme/Colors")
local BLACK = Colors.BLACK
local Fonts = import("Core/Fonts")
local FONT, FONT_MED, FONT_BOLD = Fonts.FONT, Fonts.FONT_MED, Fonts.FONT_BOLD
local Util = import("Core/Util")
local Create, Tween, Corner, List, Pad, Safe, SetFlag, IsPress = Util.Create, Util.Tween, Util.Corner, Util.List, Util.Pad, Util.Safe, Util.SetFlag, Util.IsPress
local Binding = import("Theme/Binding")
local Themed, NewText, Stroke = Binding.Themed, Binding.NewText, Binding.Stroke

function Elements:AddDropdown(opts)
	opts = opts or {}
	local window, theme = self.Window, self.Theme
	local options = opts.Options or {}
	local selected = opts.Default
	local popup = nil
	local obj = {}

	local card, _, cy = Card(self, opts, 0.42)
	obj.Instance = card

	local combo = Create("TextButton", {
		Size = UDim2.new(0.4, 0, 0, 32),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -14, 0, cy),
		AutoButtonColor = false,
		Text = "",
		BorderSizePixel = 0,
		Parent = card,
	})
	Themed(window, combo, { BackgroundColor3 = "Control", BackgroundTransparency = "ControlTransparency" })
	Corner(combo, 4)
	Stroke(window, combo, "Stroke", "StrokeTransparency")
	-- never get squeezed too small on narrow screens
	Create("UISizeConstraint", { MinSize = Vector2.new(104, 32), MaxSize = Vector2.new(240, 32), Parent = combo })
	local valueLabel = NewText(window, combo, "", {
		Size = UDim2.new(1, -30, 1, 0),
		Position = UDim2.fromOffset(10, 0),
		Font = FONT,
		TextSize = 13,
		TextTruncate = Enum.TextTruncate.AtEnd,
	})
	local arrow = NewText(window, combo, ">", {
		Size = UDim2.fromOffset(14, 14),
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -8, 0.5, 0),
		TextXAlignment = Enum.TextXAlignment.Center,
		Font = FONT_BOLD,
		TextSize = 13,
		Rotation = 90,
	}, "SubText")

	local function render()
		valueLabel.Text = selected ~= nil and tostring(selected) or "None"
	end

	local function closePopup()
		local current = popup
		if not current then
			return
		end
		popup = nil
		if window._closePopup == closePopup then
			window._closePopup = nil
		end
		for _, connection in ipairs(current.conns) do
			connection:Disconnect()
		end
		Tween(arrow, { Rotation = 90 }, 0.15)
		Tween(current.frame, { GroupTransparency = 1 }, 0.12)
		Tween(current.scale, { Scale = 0.96 }, 0.12)
		Tween(current.backdrop, { BackgroundTransparency = 1 }, 0.12)
		task.delay(0.14, function()
			current.root:Destroy()
		end)
	end

	local function openPopup()
		if window._closePopup then
			window._closePopup()
		end

		local gui = window.Gui
		local sheet = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
		local view = gui.AbsoluteSize
		local rowSize = sheet and 44 or 34
		local headerH = sheet and 46 or 0
		local listH = #options * (rowSize + 2) + 8
		local width, height, x, y

		if sheet then
			-- phones: centered sheet, up to 82% of the screen height
			width = math.min(320, view.X - 32)
			height = math.min(headerH + listH, math.floor(view.Y * 0.82))
			x = (view.X - width) / 2
			y = (view.Y - height) / 2
		else
			-- PC: under the box, or above it when there is more room there
			local origin = combo.AbsolutePosition - gui.AbsolutePosition
			local box = combo.AbsoluteSize
			width = math.max(box.X, 170)
			local below = view.Y - (origin.Y + box.Y) - 14
			local above = origin.Y - 14
			height = math.min(listH, 260)
			if height > below and above > below then
				height = math.min(height, math.max(above, rowSize + 8))
				y = origin.Y - height - 6
			else
				height = math.min(height, math.max(below, rowSize + 8))
				y = origin.Y + box.Y + 6
			end
			x = math.clamp(origin.X + box.X - width, 8, math.max(8, view.X - width - 8))
		end
		y = math.clamp(y, 6, math.max(6, view.Y - height - 6))

		local root = Create("Frame", {
			Name = "MoonDropdown",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			ZIndex = 100,
			Parent = gui,
		})
		local backdrop = Create("TextButton", {
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = BLACK,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			BorderSizePixel = 0,
			ZIndex = 100,
			Parent = root,
		})
		if sheet then
			Tween(backdrop, { BackgroundTransparency = 0.5 }, 0.18)
		end
		local frame = Create("CanvasGroup", {
			Size = UDim2.fromOffset(width, height),
			Position = UDim2.fromOffset(x, y),
			BackgroundColor3 = theme.Background,
			BackgroundTransparency = 0.02,
			BorderSizePixel = 0,
			GroupTransparency = 1,
			ZIndex = 101,
			Parent = root,
		})
		Corner(frame, 10)
		Create("UIStroke", {
			Color = theme.Border,
			Transparency = theme.BorderTransparency,
			Thickness = 1,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
			Parent = frame,
		})
		local scale = Create("UIScale", { Scale = 0.96, Parent = frame })
		Tween(frame, { GroupTransparency = 0 }, 0.16)
		Tween(scale, { Scale = 1 }, 0.2, Enum.EasingStyle.Back)

		if sheet then
			Create("TextLabel", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, 0, 0, headerH),
				Text = opts.Name or "Select",
				TextColor3 = theme.Text,
				Font = FONT_BOLD,
				TextSize = 15,
				Parent = frame,
			})
			Create("Frame", {
				Size = UDim2.new(1, -24, 0, 1),
				Position = UDim2.new(0, 12, 0, headerH - 1),
				BackgroundColor3 = theme.Text,
				BackgroundTransparency = 0.88,
				BorderSizePixel = 0,
				Parent = frame,
			})
		end

		local list = Create("ScrollingFrame", {
			Position = UDim2.fromOffset(0, headerH),
			Size = UDim2.new(1, 0, 1, -headerH),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 3,
			ScrollBarImageColor3 = theme.Accent,
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			Parent = frame,
		})
		List(list, 2)
		Pad(list, 6, 4, 6, 4)

		local selectedIndex = 1
		for index, opt in ipairs(options) do
			local isSelected = opt == selected
			local rest = isSelected and 0.92 or 1
			if isSelected then
				selectedIndex = index
			end
			local button = Create("TextButton", {
				Size = UDim2.new(1, 0, 0, rowSize),
				BackgroundColor3 = theme.Text,
				BackgroundTransparency = rest,
				AutoButtonColor = false,
				Text = "",
				BorderSizePixel = 0,
				Parent = list,
			})
			Corner(button, 6)
			Create("TextLabel", {
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -28, 1, 0),
				Position = UDim2.fromOffset(16, 0),
				Text = tostring(opt),
				TextColor3 = isSelected and theme.Accent or theme.Text,
				Font = FONT_MED,
				TextSize = sheet and 15 or 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Parent = button,
			})
			if isSelected then
				local pill = Create("Frame", {
					Size = UDim2.fromOffset(3, 16),
					AnchorPoint = Vector2.new(0, 0.5),
					Position = UDim2.new(0, 4, 0.5, 0),
					BackgroundColor3 = theme.Accent,
					BorderSizePixel = 0,
					Parent = button,
				})
				Corner(pill, "pill")
			end
			-- hover only for mouse users; press feedback for everyone (no highlight stuck on touch)
			if not sheet then
				button.MouseEnter:Connect(function()
					Tween(button, { BackgroundTransparency = 0.9 }, 0.08)
				end)
				button.MouseLeave:Connect(function()
					Tween(button, { BackgroundTransparency = rest }, 0.08)
				end)
			end
			button.InputBegan:Connect(function(input)
				if IsPress(input) then
					Tween(button, { BackgroundTransparency = 0.84 }, 0.05)
				end
			end)
			button.InputEnded:Connect(function(input)
				if IsPress(input) then
					Tween(button, { BackgroundTransparency = rest }, 0.1)
				end
			end)
			button.MouseButton1Click:Connect(function()
				obj:Set(opt)
				closePopup()
			end)
		end

		task.delay(0.03, function()
			if list.Parent then
				local rowTop = (selectedIndex - 1) * (rowSize + 2)
				list.CanvasPosition = Vector2.new(0, math.max(0, rowTop - (height - headerH) / 2 + rowSize / 2))
			end
		end)

		local conns = {}
		backdrop.MouseButton1Click:Connect(closePopup)
		if not sheet then
			-- an anchored popup would drift away from its box, so close it instead
			if self.Page then
				table.insert(conns, self.Page:GetPropertyChangedSignal("CanvasPosition"):Connect(closePopup))
			end
			table.insert(conns, window.Main:GetPropertyChangedSignal("Position"):Connect(closePopup))
			table.insert(conns, window.Main:GetPropertyChangedSignal("Size"):Connect(closePopup))
		end

		popup = { root = root, frame = frame, scale = scale, backdrop = backdrop, conns = conns }
		window._closePopup = closePopup
		Tween(arrow, { Rotation = -90 }, 0.15)
	end

	function obj:Set(value, silent)
		selected = value
		render()
		SetFlag(opts, selected)
		if not silent then
			Safe(opts.Callback, selected)
		end
	end
	function obj:Get()
		return selected
	end
	function obj:Refresh(newOptions, keepSelection)
		closePopup()
		options = newOptions or {}
		if not keepSelection or not table.find(options, selected) then
			selected = nil
			SetFlag(opts, nil)
		end
		render()
	end

	combo.MouseButton1Click:Connect(function()
		if popup then
			closePopup()
		else
			openPopup()
		end
	end)

	render()
	SetFlag(opts, selected)
	return obj
end

return Elements
end

modules["UI/Elements/Helpers"] = function(...)
-- Ready-made appearance helpers: watermark toggle, theme dropdown, accent picker, blur slider.
local import = ...

local Moon = import("Core/Moon")
local Elements = import("UI/Elements/Base")
local Util = import("Core/Util")
local Safe = Util.Safe

-- Ready-made toggle that shows/hides the built-in FPS + ping watermark
function Elements:AddWatermarkToggle(opts)
	opts = opts or {}
	local window = self.Window
	local userCallback = opts.Callback
	local default
	if opts.Default ~= nil then
		default = opts.Default
	else
		default = window.Watermark:IsVisible()
	end
	local toggle = self:AddToggle({
		Name = opts.Name or "Watermark",
		Description = opts.Description or "Shows FPS and ping",
		Default = default,
		Flag = opts.Flag or "Watermark",
		Callback = function(state)
			window.Watermark:SetVisible(state)
			Safe(userCallback, state)
		end,
	})
	window.Watermark:SetVisible(default)
	return toggle
end

-- Ready-made dropdown that switches the theme with a smooth fade
function Elements:AddThemeDropdown(opts)
	opts = opts or {}
	local window = self.Window
	local userCallback = opts.Callback
	local default = window.ThemeName
	if not table.find(Moon._order, default) then
		default = nil
	end
	return self:AddDropdown({
		Name = opts.Name or "Theme",
		Description = opts.Description,
		Options = Moon:GetThemeNames(),
		Default = default,
		Flag = opts.Flag or "Theme",
		Callback = function(name)
			window:SetTheme(name)
			Safe(userCallback, name)
		end,
	})
end

-- Ready-made color picker that recolors the whole UI live
function Elements:AddAccentPicker(opts)
	opts = opts or {}
	local window = self.Window
	local userCallback = opts.Callback
	local picker = self:AddColorPicker({
		Name = opts.Name or "Accent color",
		Description = opts.Description,
		Default = window.Theme.Accent,
		Flag = opts.Flag or "Accent",
		Presets = opts.Presets,
		Callback = function(color)
			window:SetAccent(color)
			Safe(userCallback, color)
		end,
	})
	table.insert(window._accentPickers, picker)
	return picker
end

-- Ready-made slider for the background blur strength
function Elements:AddBlurSlider(opts)
	opts = opts or {}
	local window = self.Window
	local userCallback = opts.Callback
	return self:AddSlider({
		Name = opts.Name or "Background blur",
		Description = opts.Description,
		Min = 0,
		Max = opts.Max or 30,
		Default = window._blurSize,
		Flag = opts.Flag or "Blur",
		Callback = function(value)
			window:SetBlur(value)
			Safe(userCallback, value)
		end,
	})
end

return Elements
end

